+// skipWorktreeEntries returns idx's SkipWorktree entries by name.
+func skipWorktreeEntries(idx *index.Index) map[string]*index.Entry {
+	entries := make(map[string]*index.Entry)
+	for _, e := range idx.Entries {
+		if e.SkipWorktree {
+			entries[e.Name] = e
+		}
+	}
+	return entries
