// validates it, so a target that names an invalid path fails here, before
// anything is written.
func (w *Worktree) buildResetIndex(t *object.Tree, dirs, files []string, changes merkletrie.Changes) (*index.Index, []string, error) {
	stored, err := w.r.Storer.Index()
	if err != nil {
		return nil, nil, err
	}
	// Some storages hand out the index they store, so it is copied: a reset
	// that fails before storing its index must leave the stored one as it
	// was.
	idx := copyIndex(stored)

	b := newIndexBuilder(idx)

	if changes == nil {
		if changes, err = w.diffTreeWithIndex(t, true); err != nil {
			return nil, nil, err
		}
	}

	// Index entries are the only record of the sparse-checkout state, which
	// a reset that does not restate dirs leaves untouched, so a rewritten
	// entry keeps its flag.
	skipped := skipWorktreeEntries(stored)

	removedFiles := make([]string, 0, len(changes))
	filesMap := buildFilePathMap(files)
	for _, ch := range changes {
		a, err := ch.Action()
		if err != nil {
			return nil, nil, err
		}

		var name string
		var e *object.TreeEntry

		switch a {
		case merkletrie.Modify, merkletrie.Insert:
			name = ch.To.String()
			e, err = t.FindEntry(name)
			if err != nil {
				return nil, nil, err
			}
		case merkletrie.Delete:
			name = ch.From.String()
		}

		if len(files) > 0 {
			contains := inFiles(filesMap, name)
			if !contains {
				continue
			}
		}

		b.Remove(name)
		removedFiles = append(removedFiles, name)
		if e == nil {
			continue
		}

		_, skip := skipped[name]
		b.Add(&index.Entry{
			Name:         name,
			Hash:         e.Hash,
			Mode:         e.Mode,
			SkipWorktree: skip,
		})
	}

	b.Write(idx)

	if len(dirs) > 0 {
		idx.SkipUnless(dirs)
	}

	return idx, removedFiles, nil
}

